/* ---------------------------------------------------------------------------
 * 通用工具：由术语表生成检索索引
 * 供 wordBankService / relevanceService 复用，避免重复遍历大对象。
 *
 * ⚠️ 新增领域注意（术语严谨性）：本函数只是索引构建器，不会校验译名来源。
 *    也就是说，往 domainTerms 里写错译名，索引照样能建立 —— 责任在配置侧。
 *    新增领域前请先阅读文件头部「★★★ 术语严谨性原则 ★★★」并逐条核对。
 * ------------------------------------------------------------------------ */
/**
 * 构建单个领域的检索索引
 * @returns {{
 *   exact: Map<string, string>,      // 小写单词 -> 官方中文译名
 *   vocab: Map<string, string>,      // 小写单词 -> 领域常用词中文
 *   excluded: Set<string>,           // 假阳性黑名单（小写）
 *   termCount: number
 * }}
 */
export function buildDomainIndex(domain) {
  if (!domain) {
    return { exact: new Map(), vocab: new Map(), excluded: new Set(), weight: new Map(), termCount: 0 };
  }
  const exact = new Map();
  const vocab = new Map();
  const excluded = new Set();
  const weight = new Map(); // 小写术语 -> 权重（越大排越前）

  for (const [key, zh] of Object.entries(domain.domainTerms || {})) {
    const k = key.toLowerCase();
    exact.set(k, zh);
    weight.set(k, resolveTermWeight(domain, key));
  }
  for (const [key, zh] of Object.entries(domain.domainVocabulary || {})) {
    const k = key.toLowerCase();
    if (!exact.has(k)) {
      vocab.set(k, zh);
      weight.set(k, resolveTermWeight(domain, key) * 0.6);
    }
  }
  /* —— 场景泛化词层（所有领域共享）——
   * 情感 / 行为 / 评价 / 叙事概念等「跨领域通用」的词，让 buildRelatedWords()
   * 不再只依赖专有术语，从而整体抬高召回上限。
   * 只进 vocab（不进 exact），因此卡片不会误标「官方认证」；
   * 权重 0.35 低于领域自有词汇（0.6）与专有术语（1），排序时排在后面。 */
  for (const [key, zh] of Object.entries(SCENARIO_VOCABULARY)) {
    const k = key.toLowerCase();
    if (!exact.has(k) && !vocab.has(k)) {
      vocab.set(k, zh);
      weight.set(k, 0.35);
    }
  }
  for (const t of domain.excludedTerms || []) {
    excluded.add(String(t).toLowerCase());
  }
  return { exact, vocab, excluded, weight, termCount: exact.size };
}

/**
 * 解析单个术语的权重。
 * 未来扩展领域时，只需在配置里加 domainTermTiers 即可，无需改本函数。
 *
 * domainTermTiers: { [tierName]: { weight: number, pattern?: RegExp|string, exact?: string[] } }
 *   - exact 列表里的词直接命中该权重
 *   - pattern 用于批量归类（如所有 *Relic 结尾的遗物词）
 * 未命中任何 tier 的术语使用 tierDefaults.default 或 1。
 */
export function resolveTermWeight(domain, term) {
  const tiers = domain?.domainTermTiers;
  const defaults = tiers?.tierDefaults || {};
  if (!tiers) return 1;
  const t = String(term);

  for (const [name, tier] of Object.entries(tiers)) {
    if (name === 'tierDefaults') continue;
    const list = tier.exact || [];
    if (list.some((x) => x.toLowerCase() === t.toLowerCase())) return tier.weight ?? 1;
  }
  for (const [name, tier] of Object.entries(tiers)) {
    if (name === 'tierDefaults') continue;
    if (!tier.pattern) continue;
    const re = tier.pattern instanceof RegExp ? tier.pattern : new RegExp(tier.pattern, 'i');
    if (re.test(t)) return tier.weight ?? 1;
  }
  return defaults.default ?? 1;
}

/** 归一化：小写 + 去除非字母字符，便于宽松比较 */
export function normalizeTerm(s) {
  return String(s || '').toLowerCase().replace(/[^a-z]/g, '');
}

export default {
  DEFAULT_THEME,
  DOMAIN_CATEGORY,
  DOMAIN_CATEGORY_ORDER,
  INTEREST_DOMAINS,
  DOMAIN_ORDER,
  buildDomainIndex,
  resolveTermWeight,
  normalizeTerm,
};
